'use strict';
const $=s=>document.querySelector(s);
const leagues={'eng.1':'英格蘭超級聯賽','uefa.champions':'歐洲聯賽冠軍盃','esp.1':'西班牙甲組聯賽','ita.1':'意大利甲組聯賽','ger.1':'德國甲組聯賽','fra.1':'法國甲組聯賽'};
const defaults={symbols:[{symbol:'NASDAQ:NVDA',name:'NVDA'},{symbol:'AMEX:VOO',name:'VOO'}],league:'eng.1',team:'Arsenal',footballMode:'arsenal-all'};
const storage={get(k){try{return JSON.parse(localStorage.getItem(k))}catch{return null}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
let saved=storage.get('dock-prefs-v2');
if(!saved){const old=storage.get('dock-prefs-v1');if(old){saved={...old};if(Array.isArray(old.symbols)&&old.symbols.map(x=>x.symbol).join(',')==='HSI:HSI,HKEX:700,SP:SPX')saved.symbols=structuredClone(defaults.symbols);if(!old.team)saved.team='Arsenal';}storage.set('dock-prefs-v2',saved||defaults);}

let prefs=saved&&leagues[saved.league]&&Array.isArray(saved.symbols)&&saved.symbols.length&&saved.symbols.length<=5&&saved.symbols.every(x=>x&&/^[A-Z0-9_]+:[A-Z0-9_.!/-]+$/.test(x.symbol)&&typeof x.name==='string')?saved:structuredClone(defaults);
if(!['arsenal-all','league'].includes(prefs.footballMode)){prefs.footballMode=/^(arsenal|ars|阿仙奴)$/i.test((prefs.team||'').trim())?'arsenal-all':'league';storage.set('dock-prefs-v2',prefs);}
let football=null,f1=null,footballError='',f1Error='',busy=false,wakeLock=null,wakeWanted=false,lastRefresh=0;
let hiddenAt=0,lastQuoteConnection=0;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(d,opts)=>new Intl.DateTimeFormat('zh-HK',{timeZone:'Asia/Hong_Kong',...opts}).format(new Date(d));
const localDate=d=>{const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('')};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function stamp(t){return t?'核對 '+fmt(t,{hour:'2-digit',minute:'2-digit',hour12:false}):''}
function safeURL(u,fallback){try{const p=new URL(u);return p.protocol==='https:'?p.href:fallback}catch{return fallback}}
function resource(title,sub,url){return '<a class="resource" href="'+esc(safeURL(url,'https://www.espn.com/soccer/'))+'" target="_blank" rel="noopener noreferrer"><span>'+esc(title)+'<small>'+esc(sub)+'</small></span><b>↗</b></a>'}
async function getJSON(url){if(!navigator.onLine)throw Error('離線');const r=await fetch(url,{signal:AbortSignal.timeout(14000),cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}
function tick(){const d=new Date();$('#date').textContent=fmt(d,{month:'long',day:'numeric',weekday:'short'});$('#clock').textContent=fmt(d,{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});$('#clock').dateTime=d.toISOString();updateFootballCountdowns(d.getTime());updateDockFeatures(d.getTime())}
function quoteWidget(host,symbol,attempt=0){host.replaceChildren();const wrap=document.createElement('div');wrap.className='tradingview-widget-container';const target=document.createElement('div');target.className='tradingview-widget-container__widget';wrap.append(target);const script=document.createElement('script');script.src='https://s3.tradingview.com/external-embedding/embed-widget-single-quote.js';script.async=true;script.textContent=JSON.stringify({symbol,width:'100%',isTransparent:true,colorTheme:'dark',locale:'zh_TW'});let handled=false;const failed=()=>{if(handled||!host.isConnected||host.firstChild!==wrap)return;handled=true;setQuoteState(symbol,'error');host.innerHTML='<p class="empty"><strong>報價連線暫停</strong>網絡恢復後會自動重連；也可按詳情查看來源。</p>';};script.onerror=failed;wrap.append(script);host.append(wrap);trackQuoteFrame(host,wrap,symbol);setTimeout(()=>{if(!wrap.querySelector('iframe'))failed()},18000)}
function reconnectQuotes(force=false){if(document.hidden||!navigator.onLine)return;if(force||quoteWasOffline){quoteWasOffline=false;renderStocks();if($('#detail').open&&$('#detail').dataset.kind==='stocks'){$('#detail-content').dataset.stockCharts='';renderDetail('stocks')}return}for(const item of prefs.symbols){const tile=[...$('#stock-quote').querySelectorAll('.quote-tile')].find(t=>t.dataset.symbol===item.symbol),host=tile?.querySelector('.quote-embed'),state=quoteStates.get(item.symbol);if(!host)continue;const failed=state?.state==='error'||state?.state==='loaded'&&!host.querySelector('iframe');if(failed&&Date.now()-(state?.at||0)>=DockFeatures.retryDelay(Math.max(1,state?.failures||1),30000))quoteWidget(host,item.symbol)}}
function renderStocks(){lastQuoteConnection=Date.now();const host=$('#stock-quote');host.replaceChildren();host.dataset.count=String(prefs.symbols.length);for(const item of prefs.symbols){const tile=document.createElement('div');tile.className='quote-tile';tile.dataset.symbol=item.symbol;tile.setAttribute('aria-label',item.name+' 報價');const label=document.createElement('div');label.className='quote-symbol';label.textContent=item.name;const embed=document.createElement('div');embed.className='quote-embed';tile.append(label,embed);host.append(tile);quoteWidget(embed,item.symbol)}}
function gameState(ev){return ev.status?.type?.state||ev.competitions?.[0]?.status?.type?.state||'pre'}
function gameSides(ev){const cs=ev.competitions?.[0]?.competitors||[];return {home:cs.find(x=>x.homeAway==='home'),away:cs.find(x=>x.homeAway==='away')}}
// Fixture helpers.
const ARSENAL_TEAM_ID='359';
const COMPETITIONS={'eng.1':'英超','uefa.champions':'歐聯','eng.fa':'足總盃','eng.league_cup':'聯賽盃','eng.charity':'社區盾','club.friendly':'友誼賽','friendly.emirates_cup':'酋長盃'};
function isArsenalEvent(ev){return ev.competitions?.[0]?.competitors?.some(c=>String(c.team?.id||c.id)===ARSENAL_TEAM_ID)||false}
function normalizeScheduleEvent(ev){if(!ev?.id||!Number.isFinite(Date.parse(ev.date))||!ev.competitions?.[0]?.competitors?.length)return null;return {...ev,status:ev.status||ev.competitions[0].status,competitions:ev.competitions.map(comp=>({...comp,competitors:(comp.competitors||[]).map(c=>({...c,score:typeof c.score==='object'&&c.score!==null?String(c.score.displayValue??c.score.value??'–'):String(c.score??'–'),shootoutScore:c.shootoutScore??c.score?.shootoutScore,team:{...c.team,logo:c.team?.logo||c.team?.logos?.[0]?.href}}))}))}}
function mergeArsenalFeeds(previous,results,fixtures){const clean=events=>(events||[]).map(normalizeScheduleEvent).filter(e=>e&&isArsenalEvent(e));const completed=clean(results===undefined?previous?.results:results),upcoming=clean(fixtures===undefined?previous?.fixtures:fixtures);const merged=new Map();const weight=e=>({post:2,in:1,pre:0}[gameState(e)]??0);for(const e of [...completed,...upcoming]){const old=merged.get(String(e.id));if(!old||weight(e)>=weight(old))merged.set(String(e.id),e)}return {results:completed,fixtures:upcoming,events:[...merged.values()]}}
function rankFixtureEvents(events){return [...events].sort((a,b)=>{const weight=e=>({in:0,pre:1,post:2}[gameState(e)]??1);const state=weight(a)-weight(b);if(state)return state;return gameState(a)==='post'?Date.parse(b.date)-Date.parse(a.date):Date.parse(a.date)-Date.parse(b.date)})}
function competitionLabel(ev){return COMPETITIONS[ev.league?.slug]||ev.league?.shortName||ev.league?.name||'賽事'}
function footballCountdown(ev,now=Date.now()){const type=ev.status?.type?.name||ev.competitions?.[0]?.status?.type?.name||'';if(/CANCEL|ABANDON/.test(type))return '已取消';if(/POSTPON/.test(type))return '已延期';if(/SUSPEND|DELAY/.test(type))return '暫停／延遲';const state=gameState(ev);if(state==='in')return '進行中';if(state==='post')return '已完場';if(ev.timeValid===false||ev.competitions?.[0]?.timeValid===false)return '時間待定';const remaining=Date.parse(ev.date)-now;if(!Number.isFinite(remaining))return '時間待定';if(remaining<=0)return '等待開賽';const total=Math.ceil(remaining/1000),days=Math.floor(total/86400),hours=Math.floor(total%86400/3600),minutes=Math.floor(total%3600/60),seconds=total%60;return '倒數 '+(days?days+'日 ':'')+[hours,minutes,seconds].map(n=>String(n).padStart(2,'0')).join(':')}
// End fixture helpers.
function updateFootballCountdowns(now=Date.now()){document.querySelectorAll('[data-football-countdown]').forEach(el=>{const ev=football?.events.find(e=>String(e.id)===el.dataset.footballCountdown);el.textContent=ev?(gameState(ev)==='in'&&footballHealth(now).stale?'賽況待更新':footballCountdown(ev,now)):'時間待定'})}
function isArsenalMode(){return prefs.footballMode==='arsenal-all'}
function footballHeading(){return isArsenalMode()?'Arsenal · 全部賽事':(prefs.team?prefs.team+' · ':'')+leagues[prefs.league]}
function fixtureRow(ev){return '<div class="fixture-row"><div class="fixture-competition"><span>'+esc(competitionLabel(ev))+'</span>'+(gameState(ev)!=='post'?'<span class="fixture-countdown countdown" data-football-countdown="'+esc(ev.id)+'">'+esc(footballCountdown(ev))+'</span>':'')+'</div>'+match(ev)+'</div>'}
function teamLogo(t){const u=safeURL(t?.team?.logo,'');return u?'<img src="'+esc(u)+'" alt="" loading="lazy" onerror="this.style.display=\'none\'">':''}
function match(ev){const {home,away}=gameSides(ev);if(!home||!away)return '';const state=gameState(ev);const stat=ev.status||ev.competitions?.[0]?.status;const timeKnown=ev.timeValid!==false&&ev.competitions?.[0]?.timeValid!==false;const hidden=state!=='pre'&&spoilerLocked(matchScope(ev.id));const penalty=!hidden&&/PEN|SHOOTOUT/i.test(stat?.type?.name||'');const label=state==='in'?(stat?.displayClock||'進行中'):state==='post'?fmt(ev.date,{month:'numeric',day:'numeric'})+(penalty?' 十二碼完場':' 完場'):fmt(ev.date,{month:'numeric',day:'numeric',...(timeKnown?{hour:'2-digit',minute:'2-digit',hour12:false}:{})})+(timeKnown?'':' 時間待定');const score=hidden?'<span class="replay-score-mask" aria-label="比分已隱藏">— : —</span>':state==='pre'?'VS':esc(home.score??'–')+' : '+esc(away.score??'–');const pens=!hidden&&home.shootoutScore!=null&&away.shootoutScore!=null?' · 十二碼 '+home.shootoutScore+'–'+away.shootoutScore:'';return '<div class="match"><div class="club">'+teamLogo(home)+'<span>'+esc(home.team.shortDisplayName||home.team.displayName)+'</span></div><div class="score '+(state==='in'?'live':'')+'">'+score+'<small>'+esc(label+pens)+'</small>'+(hidden?'<button type="button" class="replay-inline" data-replay-reveal="'+esc(matchScope(ev.id))+'">揭曉比分</button>':'')+'</div><div class="club away">'+teamLogo(away)+'<span>'+esc(away.team.shortDisplayName||away.team.displayName)+'</span></div></div>'}
function rankedGames(){if(!football)return [];if(isArsenalMode())return rankFixtureEvents(football.events.filter(isArsenalEvent));const q=(prefs.team||'').trim().toLowerCase();const preferred=ev=>q&&ev.competitions?.[0]?.competitors?.some(c=>[c.team.displayName,c.team.shortDisplayName,c.team.abbreviation].some(x=>x?.toLowerCase().includes(q)));let games=[...football.events];if(q&&games.some(preferred))games=games.filter(preferred);return rankFixtureEvents(games)}
function renderFootball(){ $('#league-label').textContent=footballHeading();$('#football-state').textContent=footballError?(football?(football.partial?'部份更新':'已存資料'):'連線失敗'):rankedGames().some(x=>gameState(x)==='in')?'進行中':'賽程 / 賽果';$('#football-state').classList.toggle('live',!footballError&&rankedGames().some(x=>gameState(x)==='in'));$('#football-content').innerHTML=football?rankedGames().slice(0,1).map(fixtureRow).join('')||'<p class="empty"><strong>近期未有賽事</strong>可在詳情查看已公布賽程及最近賽果。</p>':'<p class="empty"><strong>暫時未能取得賽程</strong>按詳情開啟 ESPN 或 FotMob。</p>';$('#football-time').title=footballError;$('#football-time').textContent='ESPN · '+(football?stamp(football.at):'未取得資料')+(footballError&&football?(football.partial?' · 部份資料未更新':' · 更新失敗'):'');pollHomeLineup()}
const raceTime=r=>Date.parse(r.date+'T'+(r.time||'23:59:59Z'));
function nextRace(){return f1?.races.find(r=>raceTime(r)>Date.now()-3*3600000)}
function countdown(r){if(!r.time)return '開賽時間待定';const ms=raceTime(r)-Date.now();if(ms<=0)return '已到預定開賽時間';const m=Math.floor(ms/60000),d=Math.floor(m/1440),h=Math.floor(m%1440/60);return d>0?'倒數 '+d+' 日 '+h+' 小時':'倒數 '+h+' 小時 '+(m%60)+' 分'}
const circuitImages=new Set(["albert_park","americas","bahrain","baku","catalunya","hungaroring","interlagos","jeddah","losail","marina_bay","miami","monaco","monza","red_bull_ring","rodriguez","shanghai","silverstone","spa","suzuka","vegas","villeneuve","yas_marina","zandvoort"]);
function circuitThumbnail(r){const id=r.Circuit?.circuitId;if(!/^[a-z0-9_]+$/.test(id||''))return '';return '<button type="button" class="circuit-thumb" data-circuit-id="'+esc(id)+'" aria-label="查看 '+esc(r.Circuit.circuitName)+' 賽道資料">'+(circuitImages.has(id)?'<img class="circuit-outline" src="assets/circuits/'+encodeURIComponent(id)+'.svg" alt="'+esc(r.Circuit.circuitName)+' 賽道輪廓" width="92" height="68" decoding="async">':'<span class="circuit-monogram">F1</span>')+'</button>'}
function renderF1(){const s=DockFeatures.nextSession(f1?.races),r=s?.race;f1HomeKey=homeSessionKey(s);if(r){$('#f1-content').innerHTML='<div class="race-kicker"><span>下一節 · R'+esc(r.round)+' · '+esc(s.label)+'</span><span id="f1-event-flag" class="event-flag" hidden></span></div><div class="race-hero"><div class="race-summary"><div class="race-name">'+esc(r.raceName.replace(' Grand Prix',''))+'<span style="color:#67737c"> GP</span></div><div class="race-place">'+esc(r.Circuit.circuitName)+'</div></div>'+circuitThumbnail(r)+'</div><div class="race-bottom"><span class="race-date">'+esc(fmt(s.date+'T'+(s.time||'00:00:00Z'),{month:'numeric',day:'numeric',weekday:'short',...(s.time?{hour:'2-digit',minute:'2-digit',hour12:false}:{})}))+'</span><span id="countdown" class="countdown">'+esc(DockFeatures.sessionCountdown(s))+'</span></div>'}else{$('#f1-content').innerHTML='<p class="empty"><strong>'+(f1?'本季暫無後續賽程':'暫時未能取得 F1 資料')+'</strong></p>'}updateDataHealth()}
async function loadArsenal(){const key='dock-football-arsenal-all-v1';football=storage.get(key);if(football&&!Array.isArray(football.events))football=null;if(football)renderFootball();const base='https://site.api.espn.com/apis/site/v2/sports/soccer/all/teams/'+ARSENAL_TEAM_ID+'/schedule';try{const fetchFeed=async url=>{const d=await getJSON(url);if(!Array.isArray(d.events))throw Error('賽程格式錯誤');return d.events};const feeds=await Promise.allSettled([fetchFeed(base+'?limit=100'),fetchFeed(base+'?fixture=true&limit=100')]);if(feeds.every(f=>f.status==='rejected'))throw Error('賽程及賽果暫時無法更新');const results=feeds[0].status==='fulfilled'?feeds[0].value:undefined,fixtures=feeds[1].status==='fulfilled'?feeds[1].value:undefined;football={...mergeArsenalFeeds(football,results,fixtures),at:Date.now(),mode:'arsenal-all',partial:feeds.some(f=>f.status==='rejected')};storage.set(key,football);footballError=football.partial?'部份資料未更新，請以來源網站確認':''}catch(e){footballError=e.message}renderFootball()}
async function loadFootball(){if(isArsenalMode())return loadArsenal();const key='dock-football-'+prefs.league;football=storage.get(key);if(football&&!Array.isArray(football.events))football=null;if(football)renderFootball();const from=new Date(Date.now()-3*86400000),to=new Date(Date.now()+14*86400000);try{const base='https://site.api.espn.com/apis/site/v2/sports/soccer/'+prefs.league+'/scoreboard';let data=await getJSON(base);const nextDays=data.leagues?.[0]?.calendar?.filter(d=>localDate(new Date(d))>=localDate(new Date())&&Date.parse(d)<to.getTime()).slice(0,prefs.team?3:1)||[];if(nextDays.length){const extra=await Promise.allSettled(nextDays.map(d=>getJSON(base+'?dates='+localDate(new Date(d)))));const merged=new Map((data.events||[]).map(e=>[e.id,e]));for(const item of extra)if(item.status==='fulfilled'&&Array.isArray(item.value.events))for(const ev of item.value.events)merged.set(ev.id,ev);data={...data,events:[...merged.values()]};}if(!Array.isArray(data.events))throw Error('資料格式錯誤');football={events:data.events.filter(x=>x.date&&x.competitions?.[0]?.competitors?.length>=2).map(e=>({...e,league:e.league||{slug:prefs.league,name:leagues[prefs.league]}})),at:Date.now(),league:prefs.league};storage.set(key,football);footballError=''}catch(e){footballError=e.message}renderFootball()}
async function loadF1(){f1=storage.get('dock-f1');if(f1&&!Array.isArray(f1.races))f1=null;if(f1)renderF1();try{const data=await getJSON('https://api.jolpi.ca/ergast/f1/current.json?limit=100');const races=data.MRData?.RaceTable?.Races;if(!Array.isArray(races))throw Error('賽程無法載入');f1={races:races.sort((a,b)=>raceTime(a)-raceTime(b)),season:data.MRData?.RaceTable?.season,at:Date.now()};storage.set('dock-f1',f1);f1Error=''}catch(e){f1Error=e.message}renderF1()}
async function refresh(kinds=['football','f1']){if(busy){pendingRefresh=true;return}busy=true;$('#refresh').disabled=true;try{await Promise.allSettled(kinds.map(async kind=>{try{await (kind==='football'?loadFootball():loadF1())}finally{scheduleRefresh(kind)}}));lastRefresh=Date.now();if($('#detail').open){const kind=$('#detail').dataset.kind;if(kinds.includes(kind)){if(kind==='football'&&matchView){const entry=matchCache.get(matchView.id);const event=entry?matchModel(entry.data,matchView.id).event:football?.events.find(e=>String(e.id)===matchView.id);if(!entry||Date.now()-entry.at>=DockTuning.footballInterval(event?[event]:[]))loadMatchDetail(matchView.id,true)}else renderDetail(kind)}}}finally{busy=false;$('#refresh').disabled=false;tick();if(pendingRefresh){pendingRefresh=false;if(navigator.onLine&&!document.hidden)refresh()}}}
function footballQuickLinks(games){const next=games.find(e=>gameState(e)!=='post'),recent=games.find(e=>gameState(e)==='post');return '<div class="football-quick">'+[[next,'下一場'],[recent,'最近完場']].filter(([e])=>e).map(([e,label])=>'<button type="button" data-match-id="'+esc(e.id)+'"><small>'+label+'</small><strong>'+esc(e.shortName||e.name||'比賽')+'</strong><span>陣容與數據 →</span></button>').join('')+'</div>'}
function detailFixture(ev){const notes=(ev.competitions?.[0]?.notes||[]).map(n=>n.headline).filter(Boolean).join(' · ');const sides=gameSides(ev);const label=(sides.home?.team.displayName||'主隊')+' 對 '+(sides.away?.team.displayName||'客隊')+' 陣容及數據';return '<article class="game-detail" data-reading-anchor="fixture-'+esc(ev.id)+'"><div class="fixture-heading"><span class="competition-tag">'+esc(competitionLabel(ev))+'</span><span class="muted">'+esc(fmt(ev.date,{month:'long',day:'numeric',weekday:'short'}))+'</span></div>'+match(ev)+(notes&&!spoilerLocked(matchScope(ev.id))?'<p class="helper muted">'+esc(notes)+'</p>':'')+'<button type="button" class="match-open" data-match-id="'+esc(ev.id)+'" aria-label="'+esc(label)+'">陣容 · 數據 · 賽況 <span>→</span></button></article>'}
function renderFootballDetail(c){const games=rankedGames(),future=games.filter(e=>gameState(e)!=='post'),past=games.filter(e=>gameState(e)==='post');c.innerHTML='<h2>'+esc(footballHeading())+'</h2>'+footballQuickLinks(games)+(future.length?'<h3>即場及即將舉行</h3>'+future.map(detailFixture).join(''):'<p class="empty">暫無後續賽事</p>')+(past.length?'<h3>已完賽</h3>'+past.map(detailFixture).join(''):'')+'<div class="match-source"><span>ESPN · '+esc(football?stamp(football.at):'未取得資料')+(footballError?' · 更新失敗':'')+'</span></div>'}

let stockRange='1M';
const stockRanges=[['1D','1日','1d|1'],['1M','1月','1m|30'],['3M','3月','3m|60'],['12M','1年','12m|1D'],['60M','5年','60m|1W']];
function stockChart(host,item,attempt=0){host.replaceChildren();const wrap=document.createElement('div');wrap.className='tradingview-widget-container';const target=document.createElement('div');target.className='tradingview-widget-container__widget';wrap.append(target);const script=document.createElement('script');script.src='https://s3.tradingview.com/external-embedding/embed-widget-symbol-overview.js';script.async=true;script.textContent=JSON.stringify({symbols:[[item.name,item.symbol+'|'+stockRange]],chartOnly:false,width:'100%',height:'100%',locale:'zh_TW',colorTheme:'dark',autosize:true,isTransparent:false,backgroundColor:'#191d20',widgetFontColor:'#f4f5f5',fontColor:'#aab4bd',gridLineColor:'rgba(141,150,157,0.12)',showVolume:false,showMA:false,hideDateRanges:true,hideMarketStatus:false,hideSymbolLogo:false,scalePosition:'right',scaleMode:'Normal',fontFamily:'-apple-system, BlinkMacSystemFont, sans-serif',fontSize:'10',noTimeScale:false,valuesTracking:'1',changeMode:'price-and-percent',chartType:'area',lineWidth:2,lineType:0,dateRanges:[stockRanges.find(r=>r[0]===stockRange)[2]]});let handled=false;const failed=()=>{if(handled||!host.isConnected||host.firstChild!==wrap)return;handled=true;host.innerHTML='<p class="empty">圖表暫時未能載入</p>';const notice=host.firstChild;if(attempt<2)setTimeout(()=>{if(host.isConnected&&host.firstChild===notice&&!document.hidden&&navigator.onLine)stockChart(host,item,attempt+1)},5000*(attempt+1))};script.onerror=failed;wrap.append(script);host.append(wrap);const observer=new MutationObserver(()=>{const frame=wrap.querySelector('iframe');if(frame){frame.tabIndex=-1;frame.title=item.name+' 股價圖表';observer.disconnect()}});observer.observe(wrap,{childList:true,subtree:true});setTimeout(()=>{observer.disconnect();if(!wrap.querySelector('iframe'))failed()},18000)}
function renderStockDetail(c){const key=JSON.stringify([prefs.symbols,stockRange]);if(c.dataset.stockCharts===key&&c.querySelector('.stock-charts'))return;c.dataset.stockCharts=key;c.innerHTML='<h2>股價圖表</h2><div class="chart-ranges" role="group" aria-label="圖表時段">'+stockRanges.map(([value,label])=>'<button type="button" data-stock-range="'+value+'" aria-pressed="'+(stockRange===value)+'">'+label+'</button>').join('')+'</div><div class="stock-charts">'+prefs.symbols.map((s,i)=>'<section class="stock-chart" aria-label="'+esc(s.name)+' 股價圖表"><div id="detail-chart-'+i+'" class="chart-embed"></div></section>').join('')+'</div>';prefs.symbols.forEach((s,i)=>stockChart($('#detail-chart-'+i),s))}


// Match data helpers.
const MATCH_STATS=[['possessionPct','控球率'],['totalShots','射門'],['shotsOnTarget','射正'],['wonCorners','角球'],['totalPasses','傳球'],['accuratePasses','成功傳球'],['saves','撲救'],['totalTackles','搶截'],['interceptions','截傳'],['foulsCommitted','犯規'],['offsides','越位'],['yellowCards','黃牌'],['redCards','紅牌']];
function matchModel(data,id){const comp=data.header?.competitions?.[0];if(String(data.header?.id)!==String(id)||!comp||comp.competitors?.length<2)throw Error('比賽資料不完整');const event=normalizeScheduleEvent({id:String(id),date:comp.date||data.header.date,league:data.header.league,status:comp.status,competitions:[comp]});if(!event)throw Error('比賽資料不完整');const {home,away}=gameSides(event);if(!home||!away)throw Error('球隊資料不完整');return {event,home,away,state:gameState(event),data}}
function statDisplay(side,key){const stat=side?.statistics?.find(s=>s.name===key);if(stat?.displayValue==null)return null;const value=String(stat.displayValue);return key==='possessionPct'&&!value.includes('%')?value+'%':value}
function matchStatRows(model){if(model.state==='pre')return [];const teams=model.data.boxscore?.teams||[];const home=teams.find(t=>String(t.team?.id)===String(model.home.team.id)),away=teams.find(t=>String(t.team?.id)===String(model.away.team.id));return MATCH_STATS.map(([key,label])=>({key,label,home:statDisplay(home,key),away:statDisplay(away,key)})).filter(r=>r.home!==null||r.away!==null)}
function rosterGroups(roster){const players=Array.isArray(roster?.roster)?roster.roster:[];return {starters:players.filter(p=>p.starter===true),bench:players.filter(p=>p.starter===false),unknown:players.filter(p=>typeof p.starter!=='boolean')}}
function playerStat(player,key){const stat=player.stats?.find(s=>s.name===key);const n=Number(stat?.value??stat?.displayValue);return Number.isFinite(n)&&n>0?n:0}
function importantEvents(data){return (data.keyEvents||[]).filter(e=>e.scoringPlay||e.shootout||/goal|card|substitution|penalty/.test(e.type?.type||'')).slice().sort((a,b)=>(a.period?.number&&b.period?.number?a.period.number-b.period.number:0)||(a.clock?.value||0)-(b.clock?.value||0))}
// End match data helpers.
let matchView=null,matchRequest=0;
const matchCache=new Map();
function matchTabs(){return [['lineup','陣容'],['players','表現'],['stats','數據'],['events','賽況'],['form','近況'],['h2h','對賽']].map(([id,label])=>'<button type="button" data-match-tab="'+id+'" aria-pressed="'+(matchView.tab===id)+'">'+label+'</button>').join('')}

let footballPortraitIds=null,footballPortraitRequest=null,footballPortraitAttempt=0;
function footballPhotoURL(player){const direct=player.athlete?.headshot?.href||player.athlete?.headshot;if(typeof direct==='string'&&/^https:\/\/(?:images\.fotmob\.com|a\.espncdn\.com)\//.test(direct))return direct;const id=String(player.athlete?.id||'');const photo=footballPortraitIds?.[id];return /^\d+$/.test(id)&&/^\d+$/.test(String(photo||''))?'https://images.fotmob.com/image_resources/playerimages/'+photo+'.png':''}
function footballPlayerPortrait(player){const name=player.athlete?.displayName||player.athlete?.fullName||'',initials=name.split(/\s+/).filter(Boolean).slice(0,2).map(n=>n.slice(0,1)).join('')||'–';const src=footballPhotoURL(player);return '<span class="player-portrait" aria-hidden="true"><span>'+esc(initials)+'</span>'+(src?'<img data-football-player-image src="'+esc(src)+'" alt="" width="32" height="32" loading="lazy" decoding="async">':'')+'</span>'}
function loadFootballPortraits(){if(footballPortraitIds||footballPortraitRequest||Date.now()-footballPortraitAttempt<60000)return;footballPortraitAttempt=Date.now();footballPortraitRequest=getJSON('assets/football-player-photos.json?v=lineup-portraits-1').then(data=>{if(!data||Array.isArray(data)||typeof data!=='object')throw Error('Invalid portrait IDs');const pairs=Object.entries(data);if(pairs.some(([id,photo])=>!/^\d+$/.test(id)||!/^\d+$/.test(String(photo))))throw Error('Invalid portrait IDs');footballPortraitIds=Object.fromEntries(pairs)}).catch(()=>{}).finally(()=>{footballPortraitRequest=null;if(['lineup','players'].includes(matchView?.tab)&&$('#detail').open&&$('#detail').dataset.kind==='football'){const benchOpen=$('.bench-list')?.open,starterOpen=$('.starter-list')?.open,scroll=$('#detail').scrollTop;renderMatchView();if(benchOpen&&$('.bench-list'))$('.bench-list').open=true;if(starterOpen&&$('.starter-list'))$('.starter-list').open=true;$('#detail').scrollTop=scroll}})}

function playerRow(p){const positions={G:'門將',GK:'門將',CD:'中堅','CD-L':'左中堅','CD-R':'右中堅',LB:'左閘',RB:'右閘',LM:'左中場',RM:'右中場',CM:'中場','CM-L':'左中場','CM-R':'右中場',AM:'進攻中場','AM-L':'左進攻中場','AM-R':'右進攻中場',DM:'防守中場',F:'前鋒',CF:'中鋒',LW:'左翼',RW:'右翼',SUB:'後備'};const protectedPlayer=matchView&&spoilerLocked(matchScope(matchView.id));const markers=protectedPlayer?'':[['totalGoals','入球'],['goalAssists','助攻'],['yellowCards','黃牌'],['redCards','紅牌']].map(([key,label])=>{const n=playerStat(p,key);return n?'<span class="player-tag '+(key==='redCards'?'red-tag':'')+'">'+label+' '+n+'</span>':''}).join('');const subTime=(p.plays||[]).find(x=>x.substitution)?.clock?.displayValue||'';const substitution=protectedPlayer?'':p.subbedIn?'↑ '+subTime+' 換入':p.subbedOut?'↓ '+subTime+' 換出':'';return '<li class="player-row"><span class="jersey">'+esc(p.jersey||'–')+'</span>'+footballPlayerPortrait(p)+'<span class="player-info"><strong>'+esc(p.athlete?.displayName||p.athlete?.fullName||'球員名稱待提供')+'</strong><small>'+esc(positions[p.position?.abbreviation]||p.position?.abbreviation||p.position?.displayName||'')+(substitution?' · '+esc(substitution):'')+'</small>'+(markers?'<span class="player-tags">'+markers+'</span>':'')+'</span></li>'}
function lineupPanel(model){const sides=[model.home,model.away];const selected=sides.find(s=>String(s.team.id)===matchView.team)||sides.find(s=>String(s.team.id)===ARSENAL_TEAM_ID)||sides[0];matchView.team=String(selected.team.id);const roster=(model.data.rosters||[]).find(t=>String(t.team?.id)===matchView.team);const groups=rosterGroups(roster);if(groups.starters.length||groups.bench.length||groups.unknown.length)loadFootballPortraits();const switcher='<div class="lineup-teams" role="group" aria-label="陣容球隊">'+sides.map(s=>'<button type="button" data-lineup-team="'+esc(s.team.id)+'" aria-pressed="'+(String(s.team.id)===matchView.team)+'">'+teamLogo(s)+'<span>'+esc(s.team.shortDisplayName||s.team.displayName)+'</span></button>').join('')+'</div>';if(!groups.starters.length&&!groups.bench.length&&!groups.unknown.length)return switcher+'<div class="match-empty"><strong>'+(model.state==='pre'?'陣容尚未公布':'陣容暫未提供')+'</strong></div>';const pitch=formationPitch(roster),list=groups.starters.length?'<ul class="player-list">'+groups.starters.map(playerRow).join('')+'</ul>':'<p class="empty">來源未標明正選名單。</p>';return switcher+'<div class="lineup-heading"><h3>正選 <span>'+groups.starters.length+'</span></h3><span class="formation">'+(roster.formation?'陣式 '+esc(roster.formation):'陣式未提供')+'</span></div>'+pitch+(pitch?'<details class="starter-list" data-reading-open="starters"><summary>正選名單 · 數據</summary>'+list+'</details>':list)+(groups.bench.length?'<details class="bench-list" data-reading-open="bench"><summary>後備 <span>'+groups.bench.length+'</span></summary><ul class="player-list">'+groups.bench.map(playerRow).join('')+'</ul></details>':'')+(groups.unknown.length?'<h3>其他名單（來源未標明身份）</h3><ul class="player-list">'+groups.unknown.map(playerRow).join('')+'</ul>':'')}
function statsPanel(model){const protection=protectedMatchPanel(model,'比賽數據已隱藏');if(protection)return protection;const rows=matchStatRows(model);if(!rows.length)return '<div class="match-empty"><strong>'+(model.state==='pre'?'比賽尚未開始':'統計暫未提供')+'</strong></div>';return '<div class="stats-teams"><span>'+esc(model.home.team.shortDisplayName||model.home.team.displayName)+'</span><span>主隊 · 客隊</span><span>'+esc(model.away.team.shortDisplayName||model.away.team.displayName)+'</span></div><div class="match-stats">'+rows.map(r=>'<div class="stat-row"><strong>'+esc(r.home??'–')+'</strong><span>'+esc(r.label)+'</span><strong>'+esc(r.away??'–')+'</strong></div>').join('')+'</div>'}
function eventsPanel(model){const protection=protectedMatchPanel(model,'賽況已隱藏');if(protection)return protection;const events=importantEvents(model.data);if(!events.length)return '<div class="match-empty"><strong>'+(model.state==='pre'?'等待開賽':'暫無賽況事件')+'</strong></div>';return '<ol class="match-events">'+events.map(e=>{const type=e.type?.type||'';const label=e.shootout?'十二碼決勝':type==='own-goal'?'烏龍球':e.scoringPlay?'入球':type==='substitution'?'換人':type.includes('red-card')?'紅牌':type.includes('yellow-card')?'黃牌':e.type?.text||'賽況';const names=(e.participants||[]).map(p=>p.athlete?.displayName).filter(Boolean).join(' / ');return '<li><time>'+esc(e.clock?.displayValue||'–')+'</time><div><strong>'+esc(label)+(e.team?.displayName?' · '+esc(e.team.displayName):'')+'</strong><p>'+esc(names||e.shortText||e.text||'')+'</p></div></li>'}).join('')+'</ol>'}
function formPanel(model){if(spoilerLocked(historyScope(model)))return replayGate(historyScope(model),'近期戰績已隱藏','揭曉本頁往績');const sides=[model.home,model.away];return sides.map(side=>{const recent=(model.data.lastFiveGames||[]).find(t=>String(t.team?.id)===String(side.team.id));const games=(recent?.events||[]).slice().sort((a,b)=>Date.parse(b.gameDate)-Date.parse(a.gameDate)).slice(0,5);return '<section class="recent-team"><h3>'+esc(side.team.displayName)+' · 近五場</h3>'+(games.length?games.map(e=>{const result={W:'勝',D:'和',L:'負'}[e.gameResult]||'–';return '<div class="recent-game"><span class="form-result result-'+esc(e.gameResult||'')+'">'+result+'</span><span><strong>'+esc(e.opponent?.displayName||'對手待定')+'</strong><small>'+esc(fmt(e.gameDate,{month:'numeric',day:'numeric'}))+' · '+esc(e.leagueAbbreviation||e.leagueName||'')+'</small></span><b>'+esc(e.homeTeamScore??'–')+' : '+esc(e.awayTeamScore??'–')+'</b><small>'+esc(String(e.homeTeamId)===String(side.team.id)?'主':'客')+(Number(e.homeShootoutScore)>0||Number(e.awayShootoutScore)>0?'<br>十二碼 '+esc(e.homeShootoutScore)+'–'+esc(e.awayShootoutScore):'')+'</small></div>'}).join(''):'<p class="empty">來源未提供近期戰績。</p>')+'</section>'}).join('')}
function renderMatchView(){if(!matchView||!$('#detail').open||$('#detail').dataset.kind!=='football')return;const c=$('#detail-content'),entry=matchCache.get(matchView.id);const back='<button type="button" class="match-back" data-match-back>← 返回賽程</button>';const fallback=football?.events?.find(e=>String(e.id)===matchView.id);if(!entry){c.innerHTML=back+(fallback?'<div class="match-hero">'+match(fallback)+'</div>':'')+'<div class="match-empty">'+(matchView.error?'<strong>比賽資料暫時未能載入</strong><button type="button" class="match-retry" data-match-retry>重新載入</button>':'正在讀取陣容及比賽數據…')+'</div>';return}let model;try{model=matchModel(entry.data,matchView.id)}catch{c.innerHTML=back+'<p class="empty">比賽資料不完整，請稍後再試。</p>';return}const info=model.data.gameInfo||{};const venue=info.venue?.fullName;const note=model.event.competitions?.[0]?.notes?.map(n=>n.headline).filter(Boolean).join(' · ');c.innerHTML=back+'<div class="fixture-heading"><span class="competition-tag">'+esc(competitionLabel(model.event))+'</span><span class="muted">'+esc(fmt(model.event.date,{month:'long',day:'numeric',weekday:'short'}))+'</span></div><div class="match-hero">'+match(model.event)+'</div>'+(venue?'<p class="match-venue">'+esc(venue)+(info.attendance!=null?' · 入場 '+esc(Number(info.attendance).toLocaleString('en-US')):'')+'</p>':'')+(note&&!spoilerLocked(matchScope(model.event.id))?'<p class="helper muted">'+esc(note)+'</p>':'')+'<div class="match-tabs" role="group" aria-label="比賽資料">'+matchTabs()+'</div><div id="match-panel">'+({lineup:lineupPanel,players:performancePanel,stats:statsPanel,events:eventsPanel,form:formPanel,h2h:h2hPanel}[matchView.tab]||lineupPanel)(model)+'</div><div class="match-source"><span>ESPN · '+esc(stamp(entry.at))+(matchView.error?' · 更新失敗，顯示已存資料':'')+'</span><button type="button" data-match-retry '+(matchView.loading?'disabled':'')+'>'+(matchView.loading?'更新中':'更新')+'</button></div>'}
async function loadMatchDetail(id,force=false){id=String(id);if(!/^\d+$/.test(id))return;const request=++matchRequest;const cached=matchCache.get(id);if(!force&&cached&&Date.now()-cached.at<60000){renderMatchView();return}if(matchView?.id===id){matchView.loading=true;matchView.error=false;renderMatchView()}try{await fetchFootballMatch(id,force)}catch(e){if(request===matchRequest&&matchView?.id===id)matchView.error=true}finally{if(request===matchRequest&&matchView?.id===id){matchView.loading=false;renderMatchView()}}}
function openFootballMatch(id){if(!/^\d+$/.test(String(id)))return;if(!$('#detail').open||$('#detail').dataset.kind!=='football')openDetail('football');matchView={id:String(id),tab:'lineup',team:ARSENAL_TEAM_ID,returnScroll:$('#detail').scrollTop,error:false,loading:false};renderMatchView();$('#detail').scrollTop=0;loadMatchDetail(id)}


// F1 detail data helpers.
const F1_TABS=[['schedule','賽程'],['drivers','車手'],['teams','車隊'],['sprintQualifying','衝刺排位'],['sprint','衝刺賽'],['qualifying','排位'],['results','正賽']];
function parseF1Panel(raw,type,season,round){const root=raw?.MRData;if(!root)throw Error('資料格式錯誤');if(type==='drivers'||type==='teams'){const table=root.StandingsTable;if(!table||!Array.isArray(table.StandingsLists))throw Error('積分格式錯誤');if(String(table.season)!==String(season))throw Error('積分賽季不符');const list=table.StandingsLists[0];if(list&&String(list.season)!==String(season))throw Error('積分賽季不符');const field=type==='drivers'?'DriverStandings':'ConstructorStandings';const rows=list?list[field]:[];if(!Array.isArray(rows)||rows.some(r=>!r.position||r.points==null||!(type==='drivers'?r.Driver?.driverId:r.Constructor?.constructorId)))throw Error('積分資料不完整');return {season:String(season),round:list?.round||table.round||null,rows:[...rows].sort((a,b)=>Number(a.position)-Number(b.position))}}const table=root.RaceTable;if(!table||!Array.isArray(table.Races))throw Error('成績格式錯誤');if(String(table.season)!==String(season)||String(table.round)!==String(round))throw Error('成績賽站不符');const race=table.Races[0]||null;if(race&&(String(race.season)!==String(season)||String(race.round)!==String(round)))throw Error('成績賽站不符');const field=type==='qualifying'?'QualifyingResults':type==='sprint'?'SprintResults':'Results';const rows=race?race[field]:[];if(!Array.isArray(rows)||rows.some(r=>!r.position||!r.Driver?.driverId))throw Error('成績資料不完整');return {season:String(season),round:String(round),race,rows:[...rows].sort((a,b)=>Number(a.position)-Number(b.position))}}
function f1DriverName(driver,short=false){if(!driver)return '–';return [short&&driver.givenName?driver.givenName.slice(0,1)+'.':driver.givenName,driver.familyName].filter(Boolean).join(' ')||driver.code||'–'}
function f1StatusLabel(status){if(!status)return '–';const labels={'Finished':'完賽','Lapped':'被套圈','Retired':'退賽','Did not start':'未起步','Disqualified':'取消資格','Not classified':'未列名','Withdrawn':'退出','Did not qualify':'未能晉級'};const lap=status.match(/^\+(\d+) Laps?$/);return lap?'落後 '+lap[1]+' 圈':labels[status]||status}
function f1Position(row){const labels={R:'RET',D:'DSQ',E:'EXC',W:'DNS',F:'DNQ',N:'NC'};return labels[row.positionText]||row.positionText||row.position||'–'}
function f1ResultTime(row){return row.Time?.time||f1StatusLabel(row.status)}
// End F1 detail data helpers.
let f1Tab='schedule',f1ResultRound=null,f1SprintRound=null,f1DetailSeason=null;

// Sprint qualifying data helpers.
function isSprintType(type){return type==='sprintQualifying'||type==='sprint'}
function hasF1RaceResults(type){return ['qualifying','results','sprintQualifying','sprint'].includes(type)}
function f1SessionLabel(type){return {qualifying:'排位賽',results:'正賽',sprintQualifying:'衝刺排位賽',sprint:'衝刺賽'}[type]||'成績'}
function f1LapSeconds(value){if(value==null||!Number.isFinite(Number(value))||Number(value)<=0)return '–';const ms=Math.round(Number(value)*1000);return Math.floor(ms/60000)+':'+String(Math.floor(ms%60000/1000)).padStart(2,'0')+'.'+String(ms%1000).padStart(3,'0')}
function findSprintQualifyingSession(sessions,race,season){if(!Array.isArray(sessions))throw Error('衝刺排位場次格式錯誤');const target=race.SprintQualifying?.date?Date.parse(race.SprintQualifying.date+'T'+(race.SprintQualifying.time||'12:00:00Z')):null;const raceAt=raceTime(race);const matches=sessions.filter(s=>String(s.year)===String(season)&&s.session_name==='Sprint Qualifying'&&!s.is_cancelled&&Number.isFinite(Date.parse(s.date_start))&&(target?Math.abs(Date.parse(s.date_start)-target)<=36*3600000:Date.parse(s.date_start)>=raceAt-4*86400000&&Date.parse(s.date_start)<=raceAt));if(matches.length>1)throw Error('衝刺排位場次不明確');return matches[0]||null}
function sprintQualifyingModel(results,drivers,session,race,season){if(!Array.isArray(results)||!Array.isArray(drivers))throw Error('衝刺排位成績格式錯誤');if(results.some(r=>String(r.session_key)!==String(session.session_key)||String(r.meeting_key)!==String(session.meeting_key)||r.driver_number==null))throw Error('衝刺排位場次不符');const people=new Map(drivers.filter(d=>String(d.session_key)===String(session.session_key)).map(d=>[String(d.driver_number),d]));const rows=results.map(r=>{const person=people.get(String(r.driver_number));const times=Array.isArray(r.duration)?r.duration:[];const position=Number.isFinite(Number(r.position))&&Number(r.position)>0?String(r.position):'999';return {position,positionText:r.dsq?'D':r.dns?'W':position==='999'?'N':position,number:String(r.driver_number),Driver:{driverId:'openf1-'+r.driver_number,givenName:person?.first_name||'',familyName:person?.last_name||person?.full_name||'#'+r.driver_number,headshot:person?.headshot_url||''},Constructor:{name:person?.team_name||'–'},SQ1:f1LapSeconds(times[0]),SQ2:f1LapSeconds(times[1]),SQ3:f1LapSeconds(times[2])}}).sort((a,b)=>Number(a.position)-Number(b.position));return {season:String(season),round:String(race.round),race,rows,source:'OpenF1',sessionDate:session.date_start}}
// End sprint qualifying data helpers.
const sprintSessionCache=new Map();
async function loadSprintQualifying(season,round,force=false){const race=f1?.races.find(r=>String(r.round)===String(round));if(!race||(!race.Sprint&&!race.SprintQualifying))return {season:String(season),round:String(round),race:race||null,rows:[],source:'OpenF1'};let cached=sprintSessionCache.get(season)||storage.get('dock-openf1-sprint-sessions-'+season);if(force||!cached||!Array.isArray(cached.sessions)||Date.now()-cached.at>3600000){const sessions=await getJSON('https://api.openf1.org/v1/sessions?year='+season+'&session_name=Sprint%20Qualifying');if(!Array.isArray(sessions))throw Error('衝刺排位場次格式錯誤');cached={sessions,at:Date.now()};sprintSessionCache.set(season,cached);storage.set('dock-openf1-sprint-sessions-'+season,cached)}const session=findSprintQualifyingSession(cached.sessions,race,season);if(!session||Date.parse(session.date_end)>Date.now())return {season:String(season),round:String(round),race,rows:[],source:'OpenF1'};const [results,drivers]=await Promise.all([getJSON('https://api.openf1.org/v1/session_result?session_key='+encodeURIComponent(session.session_key)),getJSON('https://api.openf1.org/v1/drivers?session_key='+encodeURIComponent(session.session_key))]);return sprintQualifyingModel(results,drivers,session,race,season)}
function f1RaceChoices(){const races=f1?.races||[];return isSprintType(f1Tab)?races.filter(r=>r.Sprint||r.SprintQualifying):races}

const f1PanelCache=new Map();
function f1Season(){return /^\d{4}$/.test(String(f1?.season))?String(f1.season):null}
function selectedF1Round(){const races=f1RaceChoices();if(!races.length)return null;const sprint=isSprintType(f1Tab),chosen=sprint?f1SprintRound:f1ResultRound;if(chosen&&races.some(r=>String(r.round)===chosen))return chosen;const past=races.filter(r=>{const session=sprint?(f1Tab==='sprintQualifying'?r.SprintQualifying:r.Sprint):null;const at=session?.date?Date.parse(session.date+'T'+(session.time||'23:59:59Z')):raceTime(r);return at<Date.now()-(sprint?2:3)*3600000});const round=String((past.at(-1)||races[0]).round);if(sprint)f1SprintRound=round;else f1ResultRound=round;return round}
function f1PanelContext(){const season=f1Season(),type=f1Tab,round=hasF1RaceResults(type)?selectedF1Round():null;return {season,type,round,key:season&&type!=='schedule'&&(round||['drivers','teams'].includes(type))?'dock-f1-panel-v1-'+season+'-'+type+(round?'-'+round:''):null}}
function f1PanelEntry(context){if(!context.key)return null;if(!f1PanelCache.has(context.key)){const saved=storage.get(context.key);f1PanelCache.set(context.key,{data:saved?.data?.season===context.season&&Array.isArray(saved.data.rows)&&(!context.round||saved.data.round===context.round)?saved.data:null,at:saved?.at||0,loading:false,error:'',attempt:0})}return f1PanelCache.get(context.key)}
function refreshF1Detail(){if($('#detail').open&&$('#detail').dataset.kind==='f1')renderF1Detail($('#detail-content'))}
async function loadF1Panel(force=false){const context=f1PanelContext(),entry=f1PanelEntry(context);if(!entry||entry.loading||(!force&&entry.data&&Date.now()-entry.at<f1RefreshInterval()))return;entry.loading=true;entry.error='';entry.attempt=Date.now();refreshF1Detail();try{if(context.type==='sprintQualifying')entry.data=await loadSprintQualifying(context.season,context.round,force);else{const suffix=context.type==='drivers'?'driverstandings':context.type==='teams'?'constructorstandings':context.round+'/'+(context.type==='qualifying'?'qualifying':context.type==='sprint'?'sprint':'results');const raw=await getJSON('https://api.jolpi.ca/ergast/f1/'+context.season+'/'+suffix+'.json?limit=100');entry.data=parseF1Panel(raw,context.type,context.season,context.round)}entry.at=Date.now();storage.set(context.key,{data:entry.data,at:entry.at})}catch(e){entry.error='更新失敗'}finally{entry.loading=false;if(f1PanelContext().key===context.key)refreshF1Detail()}}
