function f1MediaKey(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function f1MediaURL(url){return typeof url==='string'&&/^https:\/\/media\.formula1\.com\//.test(url)?url:''}
function f1PortraitURL(driver){const direct=f1MediaURL(driver?.headshot);if(direct)return direct;const id=F1_MEDIA.drivers[driver?.driverId]?driver.driverId:F1_MEDIA.names[f1MediaKey([driver?.givenName,driver?.familyName].filter(Boolean).join(' '))];return f1MediaURL(F1_MEDIA.drivers[id])}
function f1Portrait(driver){const src=f1PortraitURL(driver),initials=[driver?.givenName?.slice(0,1),driver?.familyName?.slice(0,1)].filter(Boolean).join('')||'–';return '<span class="f1-portrait" aria-hidden="true"><span>'+esc(initials)+'</span>'+(src?'<img data-f1-image src="'+esc(src)+'" alt="" loading="lazy" decoding="async" width="32" height="32">':'')+'</span>'}
function f1TeamId(team){if(F1_MEDIA.teams[team?.constructorId])return team.constructorId;const aliases={alpine:'alpine',alpinef1team:'alpine',astonmartin:'aston_martin',audi:'audi',cadillac:'cadillac',cadillacf1team:'cadillac',ferrari:'ferrari',haas:'haas',haasf1team:'haas',mclaren:'mclaren',mercedes:'mercedes',rb:'rb',rbf1team:'rb',racingbulls:'rb',redbull:'red_bull',redbullracing:'red_bull',williams:'williams'};return aliases[f1MediaKey(team?.name)]||''}
function f1TeamBadge(team,large=false){const src=f1MediaURL(F1_MEDIA.teams[f1TeamId(team)]),name=team?.name||'–';return '<span class="f1-team-identity '+(large?'f1-team-main':'')+'"><span class="f1-team-logo" aria-hidden="true"><span>'+esc(name.slice(0,1))+'</span>'+(src?'<img data-f1-image src="'+esc(src)+'" alt="" loading="lazy" decoding="async" width="24" height="24">':'')+'</span><span class="f1-team-label">'+esc(name)+'</span></span>'}
function f1TeamCell(team){return f1TeamBadge(team,true)}

function f1DriverCell(row,short=false){const teams=row.Constructor?[row.Constructor]:row.Constructors||[];return '<span class="f1-person">'+f1Portrait(row.Driver)+'<span class="f1-person-copy"><strong>'+esc(f1DriverName(row.Driver,short))+'</strong><span class="f1-affiliations">'+teams.map(t=>f1TeamBadge(t)).join('')+'</span></span></span>'}
function f1StandingsPanel(data,type){if(!data.rows.length)return '<p class="f1-empty">積分尚未公布</p>';const drivers=type==='drivers';return '<div class="f1-section-meta">'+esc(data.season)+' · 第 '+esc(data.round||'–')+' 站後</div><table class="f1-table f1-standings"><caption class="sr-only">'+(drivers?'車手積分':'車隊積分')+'</caption><colgroup><col class="rank-col"><col><col class="points-col"><col class="wins-col"></colgroup><thead><tr><th scope="col">名次</th><th scope="col">'+(drivers?'車手／車隊':'車隊')+'</th><th scope="col">積分</th><th scope="col">勝場</th></tr></thead><tbody>'+data.rows.map(r=>'<tr><td class="f1-rank">'+esc(f1Position(r))+'</td><td class="f1-name">'+(drivers?f1DriverCell(r):f1TeamCell(r.Constructor))+'</td><td class="f1-points">'+esc(r.points)+'</td><td>'+esc(r.wins??'–')+'</td></tr>').join('')+'</tbody></table>'}
function f1RacePicker(){return '<label class="f1-race-picker">賽站<select id="f1-race-select" aria-label="F1 成績賽站">'+f1RaceChoices().map(r=>'<option value="'+esc(r.round)+'" '+(String(r.round)===selectedF1Round()?'selected':'')+'>R'+esc(r.round)+' · '+esc(r.raceName.replace(' Grand Prix',' GP'))+' · '+esc(fmt(r.date+'T'+(r.time||'00:00:00Z'),{month:'numeric',day:'numeric'}))+'</option>').join('')+'</select></label>'}
function f1ResultsPanel(data,type){if(!data.rows.length)return '<p class="f1-empty">'+f1SessionLabel(type)+'成績尚未公布</p>';const meta='<div class="f1-section-meta">'+esc(data.race.raceName)+' · R'+esc(data.round)+' · '+esc(f1SessionLabel(type))+'</div>';const shootout=type==='sprintQualifying',prefix=shootout?'SQ':'Q';if(type==='qualifying'||shootout)return meta+'<table class="f1-table f1-qualifying"><caption class="sr-only">'+f1SessionLabel(type)+'成績</caption><colgroup><col class="q-rank"><col class="q-name"><col class="q-time"><col class="q-time"><col class="q-time"></colgroup><thead><tr><th scope="col">名次</th><th scope="col">車手</th><th scope="col">'+prefix+'1</th><th scope="col">'+prefix+'2</th><th scope="col">'+prefix+'3</th></tr></thead><tbody>'+data.rows.map(r=>'<tr><td class="f1-rank">'+esc(f1Position(r))+'</td><td class="f1-name">'+f1DriverCell(r,true)+'</td><td class="f1-lap">'+esc(r[prefix+'1']||'–')+'</td><td class="f1-lap">'+esc(r[prefix+'2']||'–')+'</td><td class="f1-lap">'+esc(r[prefix+'3']||'–')+'</td></tr>').join('')+'</tbody></table>';return meta+'<table class="f1-table f1-results"><caption class="sr-only">'+f1SessionLabel(type)+'成績</caption><colgroup><col class="r-rank"><col class="r-name"><col class="r-time"><col class="r-points"></colgroup><thead><tr><th scope="col">名次</th><th scope="col">車手</th><th scope="col">時間／狀態</th><th scope="col">分</th></tr></thead><tbody>'+data.rows.map(r=>'<tr><td class="f1-rank">'+esc(f1Position(r))+'</td><td class="f1-name">'+f1DriverCell(r,true)+(r.FastestLap?.rank==='1'?'<small class="fastest-lap">最快圈 '+esc(r.FastestLap.Time?.time||'')+'</small>':'')+'</td><td class="f1-finish"><strong>'+esc(f1ResultTime(r))+'</strong><small>'+esc(r.laps??'–')+' 圈 · '+(r.grid==='0'?'起步位 –':'起步 '+esc(r.grid??'–'))+'</small>'+(r.Time?.time&&r.status!=='Finished'?'<small>'+esc(f1StatusLabel(r.status))+'</small>':'')+'</td><td class="f1-points">'+esc(r.points??'–')+'</td></tr>').join('')+'</tbody></table>'}
function f1SchedulePanel(){const r=nextRace();return (r?'<div class="f1-detail-race"><div><h3>'+esc(r.raceName)+'</h3><p>'+esc(r.Circuit.circuitName)+'</p></div>'+circuitThumbnail(r)+'</div>'+[['FirstPractice','練習 1'],['SecondPractice','練習 2'],['ThirdPractice','練習 3'],['SprintQualifying','衝刺排位'],['Sprint','衝刺賽'],['Qualifying','排位賽'],['race','正賽']].filter(([k])=>k==='race'||r[k]).map(([k,n])=>{const s=k==='race'?r:r[k];return '<div class="schedule-row"><span>'+n+'</span><span>'+esc(fmt(s.date+'T'+(s.time||'00:00:00Z'),{month:'numeric',day:'numeric',...(s.time?{hour:'2-digit',minute:'2-digit',hour12:false}:{})}))+(s.time?'':' · 時間待定')+'</span></div>'}).join(''):'')+'<h3>餘下賽程</h3>'+((f1?.races||[]).filter(r=>raceTime(r)>Date.now()-3*3600000).map(r=>'<div class="schedule-row"><span>'+esc(r.raceName)+'</span><span>'+esc(fmt(r.date+'T'+(r.time||'00:00:00Z'),{month:'numeric',day:'numeric',...(r.time?{hour:'2-digit',minute:'2-digit',hour12:false}:{})}))+(r.time?'':' · 時間待定')+'</span></div>').join('')||'<p class="f1-empty">暫無後續賽程</p>')}
function renderF1Detail(c){if(circuitView){renderCircuitView();return}const season=f1Season();if(f1DetailSeason!==season){f1ResultRound=null;f1SprintRound=null;f1DetailSeason=season}const context=f1PanelContext(),entry=f1PanelEntry(context);let panel;if(f1Tab==='schedule')panel=f1SchedulePanel();else if(!season)panel='<p class="f1-empty">尚未取得賽季資料</p>';else if(!context.key)panel='<p class="f1-empty">暫無賽站資料</p>';else if(entry?.data)panel=f1ReplayGate(f1Tab,season,context.round,entry)||(['drivers','teams'].includes(f1Tab)?f1StandingsPanel(entry.data,f1Tab):f1ResultsPanel(entry.data,f1Tab));else panel='<p class="f1-empty">'+(entry?.error?'資料暫時未能載入':'正在讀取資料…')+'</p>';c.innerHTML='<div class="f1-detail-title"><h2>Formula 1</h2><span>'+esc(season||'本季')+' · 香港時間</span></div><div class="f1-tabs" role="group" aria-label="F1 資料">'+F1_TABS.map(([id,label])=>'<button type="button" data-f1-tab="'+id+'" aria-pressed="'+(f1Tab===id)+'">'+label+'</button>').join('')+'</div>'+(hasF1RaceResults(f1Tab)?f1RacePicker():'')+'<div id="f1-detail-panel">'+panel+'</div><div class="match-source"><span>'+esc(entry?.data?.source||(f1Tab==='sprintQualifying'?'OpenF1':'Jolpica F1'))+' · '+esc(f1Tab==='schedule'?f1?stamp(f1.at):'未取得資料':entry?.data?stamp(entry.at):'未取得資料')+((f1Tab==='schedule'?f1Error:entry?.error)?' · 更新失敗'+(entry?.data?'，顯示已存資料':''):'')+'</span><button type="button" data-f1-refresh '+(entry?.loading?'disabled':'')+'>'+(entry?.loading?'更新中':'更新')+'</button></div>';if(f1Tab!=='schedule'&&context.key&&!entry.loading&&(!entry.data||Date.now()-entry.at>=f1RefreshInterval())&&Date.now()-entry.attempt>30000)loadF1Panel()}

function renderDetail(kind){const c=$('#detail-content');$('#detail').dataset.kind=kind;if(kind==='stocks'){renderStockDetail(c)}else if(kind==='football'){if(matchView){renderMatchView();return}renderFootballDetail(c)}else if(kind==='f1'){renderF1Detail(c)}else if(kind==='news'){renderNewsDetail(c)}}
function openDetail(kind){if(!['stocks','football','f1','news'].includes(kind))return;saveReadingState();$('#detail').dataset.kind=kind;restoreReadingSelection(kind);readingRenderedKey='';matchRequest++;$('#detail-eyebrow').textContent='DESK DOCK / '+({stocks:'MARKETS',football:'FOOTBALL',f1:'FORMULA 1',news:'TECH NEWS'}[kind]);if(!$('#detail').open)$('#detail').showModal();renderDetail(kind);if(kind==='football'&&matchView)loadMatchDetail(matchView.id);if(kind==='f1'&&circuitView){loadCircuitFacts();loadCircuitWinners(circuitView.id)}}
document.addEventListener('click',ev=>{const reveal=ev.target.closest('[data-replay-reveal]');if(reveal){revealReplay(reveal.dataset.replayReveal);return}if(ev.target.closest('#spoiler-toggle')){toggleReplay();return}const circuit=ev.target.closest('[data-circuit-id]');if(circuit){openCircuit(circuit.dataset.circuitId);return}const f1tab=ev.target.closest('[data-f1-tab]');if(f1tab){if(F1_TABS.some(t=>t[0]===f1tab.dataset.f1Tab)){f1Tab=f1tab.dataset.f1Tab;renderF1Detail($('#detail-content'))}return}if(ev.target.closest('[data-f1-refresh]')){if(f1Tab==='schedule')loadF1().then(refreshF1Detail);else loadF1Panel(true);return}const fixture=ev.target.closest('[data-match-id]');if(fixture){openFootballMatch(fixture.dataset.matchId);return}const tab=ev.target.closest('[data-match-tab]');if(tab&&matchView){if(['lineup','players','stats','events','form','h2h'].includes(tab.dataset.matchTab)){matchView.tab=tab.dataset.matchTab;renderMatchView()}return}const team=ev.target.closest('[data-lineup-team]');if(team&&matchView){matchView.team=team.dataset.lineupTeam;renderMatchView();return}if(ev.target.closest('[data-match-back]')&&matchView){const scroll=matchView.returnScroll;matchView=null;matchRequest++;renderDetail('football');$('#detail').scrollTop=scroll;return}if(ev.target.closest('[data-match-retry]')&&matchView){loadMatchDetail(matchView.id,true);return}const range=ev.target.closest('[data-stock-range]');if(range){if(stockRanges.some(r=>r[0]===range.dataset.stockRange)&&stockRange!==range.dataset.stockRange){stockRange=range.dataset.stockRange;renderStockDetail($('#detail-content'))}return}const b=ev.target.closest('[data-detail]');if(b)openDetail(b.dataset.detail);});
$('#close-detail').onclick=()=>{saveReadingState();$('#detail').close()};$('#close-settings').onclick=()=>$('#preferences').close();for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',ev=>{const r=d.getBoundingClientRect();if(ev.target===d&&(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)){if(d.id==='detail')saveReadingState();d.close()}});
function syncFootballFields(){$('#league-preferences').hidden=$('#football-mode').value==='arsenal-all'}
$('#football-mode').onchange=syncFootballFields;
$('#settings').onclick=()=>{$('#symbols').value=prefs.symbols.map(s=>s.symbol+','+s.name).join('\n');$('#football-mode').value=prefs.footballMode;syncFootballFields();$('#league').value=prefs.league;$('#team').value=prefs.team||'';showNightSettings();$('#spoiler-enabled').checked=spoilerEnabled();$('#display-mode').value=DockExtras.displayMode(prefs.displayMode);$('#form-error').textContent='';$('#preferences').showModal()};
$('#prefs-form').onsubmit=async ev=>{ev.preventDefault();const lines=$('#symbols').value.trim().split(/\r?\n/).filter(x=>x.trim());const symbols=lines.map(line=>{const [symbol,...rest]=line.split(',');return {symbol:symbol.trim().toUpperCase(),name:rest.join(',').trim()||symbol.trim().toUpperCase()}});if(!symbols.length||symbols.length>5||symbols.some(s=>!/^[A-Z0-9_]+:[A-Z0-9_.!/-]+$/.test(s.symbol)||s.name.length>30)){$('#form-error').textContent='請輸入 1 至 5 項有效代號，例如 HKEX:700,騰訊；名稱最多 30 字。';return}if(busy){$('#form-error').textContent='正在更新資料，請稍候再儲存。';return}const previousSpoiler=spoilerEnabled();const night=readNightSettings();if(!$('#night-start').value||!$('#night-end').value||night.start===night.end){$('#form-error').textContent='請選擇不同的夜間開始及結束時間。';return}const stockChanged=JSON.stringify(prefs.symbols)!==JSON.stringify(symbols),footballChanged=prefs.footballMode!==$('#football-mode').value||prefs.league!==$('#league').value||prefs.team!==$('#team').value.trim();prefs={...prefs,symbols,footballMode:$('#football-mode').value,league:$('#league').value,team:$('#team').value.trim(),night,displayMode:DockExtras.displayMode($('#display-mode').value),spoilerMode:$('#spoiler-enabled').checked};storage.set('dock-prefs-v2',prefs);if(stockChanged)renderStocks();if(footballChanged){football=null;footballError='';$('#football-content').innerHTML='<p class="loading">正在讀取賽程…</p>'}$('#preferences').close();applyDisplayMode();applyReplayPreferences(previousSpoiler);tick();toast('已儲存設定');if(footballChanged)await refresh(['football'])};
$('#refresh').onclick=()=>{if(!busy){reconnectQuotes(true);refresh();loadNews(true);toast('正在更新資訊')}};
async function requestWake(){if(!('wakeLock' in navigator)){toast('此瀏覽器未支援亮屏；可把系統自動鎖定設為「永不」。');return}try{wakeLock=await navigator.wakeLock.request('screen');$('#wake').classList.add('active');$('#wake').setAttribute('aria-pressed','true');$('#wake').setAttribute('aria-label','關閉保持亮屏');wakeLock.addEventListener('release',()=>{$('#wake').classList.remove('active');$('#wake').setAttribute('aria-pressed','false')});return true}catch{toast('暫未能保持亮屏；請檢查低耗電模式或系統設定。');return false}}
$('#wake').onclick=async()=>{if(wakeWanted){wakeWanted=false;if(wakeLock)await wakeLock.release();$('#wake').setAttribute('aria-label','啟用保持亮屏');toast('已關閉保持亮屏')}else{wakeWanted=true;const ok=await requestWake();if(ok)toast('保持亮屏已啟用');else wakeWanted=false}};
document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();return}tick();if(wakeWanted&&(!wakeLock||wakeLock.released))requestWake();reconnectQuotes();hiddenAt=0;maintainConnections()});
window.addEventListener('online',()=>{footballFailures=0;f1Failures=0;tick();quoteWasOffline=true;reconnectQuotes();refresh()});window.addEventListener('offline',()=>{quoteWasOffline=true;tick()});
window.addEventListener('pageshow',ev=>{if(ev.persisted){tick();reconnectQuotes();maintainConnections()}});
prefs.night=DockFeatures.nightSettings(prefs.night);prefs.displayMode=DockExtras.displayMode(prefs.displayMode);applyDisplayMode();prefs.spoilerMode=prefs.spoilerMode===true;updateReplayControl();setupReading();tick();setInterval(tick,1000);renderStocks();refresh();startNews();

document.addEventListener('error',ev=>{if(ev.target instanceof HTMLImageElement&&ev.target.classList.contains('circuit-outline'))ev.target.closest('.circuit-thumb')?.remove()},true);

document.addEventListener('change',ev=>{if(ev.target.id==='f1-race-select'){const round=String(ev.target.value);if(f1RaceChoices().some(r=>String(r.round)===round)){if(isSprintType(f1Tab))f1SprintRound=round;else f1ResultRound=round;renderF1Detail($('#detail-content'))}}});

document.addEventListener('error',ev=>{if(ev.target instanceof HTMLImageElement&&ev.target.hasAttribute('data-f1-image'))ev.target.remove()},true);

document.addEventListener('error',ev=>{if(ev.target instanceof HTMLImageElement&&ev.target.hasAttribute('data-football-player-image'))ev.target.remove()},true);

setInterval(maintainConnections,15000);
